import { AevkoFloating } from '../shared/floating.directive';
import {
  ViewEncapsulation,
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  booleanAttribute,
  contentChild,
  contentChildren,
  effect,
  inject,
  input,
  model,
} from '@angular/core';

@Directive({
  selector: '[aevkoDropdownMenuTrigger]',
  standalone: true,
  host: { 'data-slot': 'dropdown-menu-trigger' },
})
export class AevkoDropdownMenuTrigger {
  readonly element = inject<ElementRef<HTMLElement>>(ElementRef);
}
@Directive({
  selector: 'button[aevkoDropdownMenuItem]',
  standalone: true,
  host: {
    type: 'button',
    role: 'menuitem',
    tabindex: '-1',
    'data-slot': 'dropdown-menu-item',
    '[disabled]': 'disabled()',
    '[attr.aria-disabled]': 'disabled() ? "true" : null',
  },
})
export class AevkoDropdownMenuItem {
  readonly element = inject<ElementRef<HTMLButtonElement>>(ElementRef);
  readonly disabled = input(false, { transform: booleanAttribute });
}

@Component({
  selector: 'aevko-dropdown-menu',
  standalone: true,
  imports: [AevkoFloating],
  templateUrl: './dropdown-menu.component.html',
  styleUrl: './dropdown-menu.component.css',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'dropdown-menu-root',
    '(document:pointerdown)': 'dismissOutside($event)',
    '(document:focusin)': 'dismissOutside($event)',
    '(click)': 'click($event)',
    '(keydown)': 'keydown($event)',
  },
})
export class AevkoDropdownMenu {
  private readonly hostElement = inject<ElementRef<HTMLElement>>(ElementRef);
  protected dismissOutside(event: Event): void {
    if (this.open() && !event.composedPath().includes(this.hostElement.nativeElement)) {
      this.open.set(false);
    }
  }
  readonly label = input.required<string>();
  readonly id = input('aevko-dropdown-menu');
  readonly open = model(false);
  readonly align = input<'start' | 'end'>('start');
  private readonly trigger = contentChild(AevkoDropdownMenuTrigger);
  private readonly items = contentChildren(AevkoDropdownMenuItem, { descendants: true });
  constructor() {
    effect(() => {
      const trigger = this.trigger()?.element.nativeElement;
      if (!trigger) return;
      trigger.setAttribute('aria-haspopup', 'menu');
      trigger.setAttribute('aria-expanded', String(this.open()));
      trigger.setAttribute('aria-controls', this.id());
    });
  }
  protected click(event: MouseEvent): void {
    const target = event.target as Element;
    if (target.closest('[aevkoDropdownMenuTrigger]')) {
      this.open.update((v) => !v);
      if (this.open()) setTimeout(() => this.focus(0));
    } else if (target.closest('[aevkoDropdownMenuItem]')) this.open.set(false);
  }
  protected keydown(event: KeyboardEvent): void {
    if (
      !this.open() &&
      ['ArrowDown', 'Enter', ' '].includes(event.key) &&
      (event.target as Element).closest('[aevkoDropdownMenuTrigger]')
    ) {
      event.preventDefault();
      this.open.set(true);
      setTimeout(() => this.focus(0));
      return;
    }
    if (!this.open()) return;
    const enabled = this.items().filter(
      (item) => !item.disabled() && !item.element.nativeElement.disabled,
    );
    const current = enabled.findIndex((item) => item.element.nativeElement === event.target);
    if (event.key === 'Escape') {
      event.preventDefault();
      this.open.set(false);
      this.trigger()?.element.nativeElement.focus();
    } else if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
      event.preventDefault();
      const index =
        event.key === 'Home'
          ? 0
          : event.key === 'End'
            ? enabled.length - 1
            : (current + (event.key === 'ArrowUp' ? -1 : 1) + enabled.length) % enabled.length;
      enabled[index]?.element.nativeElement.focus();
    }
  }
  private focus(index: number): void {
    this.items()
      .filter((item) => !item.disabled() && !item.element.nativeElement.disabled)
      [index]?.element.nativeElement.focus();
  }
}

:where(aevko-dropdown-menu) {
  display: inline-block;
  position: relative;
}
:where(aevko-dropdown-menu) > [data-slot='dropdown-menu-content'] {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: 0;
  box-shadow: var(--aevko-shadow, 0 4px 16px rgb(0 0 0 / 0.08));
  display: grid;
  gap: 0.125rem;
  inline-size: max-content;
  min-inline-size: 12rem;
  padding: 0.25rem;
  position: absolute;
  inset-block-start: calc(100% + 0.375rem);
  z-index: 35;
}
:where(aevko-dropdown-menu) > [data-slot='dropdown-menu-content'][data-align='start'] {
  inset-inline-start: 0;
}
:where(aevko-dropdown-menu) > [data-slot='dropdown-menu-content'][data-align='end'] {
  inset-inline-end: 0;
}
:where(aevko-dropdown-menu) [aevkoDropdownMenuItem] {
  background: transparent;
  border: 0;
  border-radius: 0;
  color: inherit;
  min-block-size: 2.25rem;
  padding: 0.5rem 0.625rem;
  text-align: start;
}
:where(aevko-dropdown-menu) [aevkoDropdownMenuItem]:hover,
:where(aevko-dropdown-menu) [aevkoDropdownMenuItem]:focus-visible {
  background: var(--aevko-background, #f4f4f5);
  outline: 2px solid var(--aevko-focus, #71717a);
  outline-offset: -2px;
}
:where(aevko-dropdown-menu) > [hidden] {
  display: none;
}

@media (prefers-reduced-motion: no-preference) {
  :where(aevko-dropdown-menu) [data-slot='dropdown-menu-content']:not([hidden]) {
    animation: aevko-dropdown-menu-enter 140ms cubic-bezier(0.2, 0, 0, 1);
  }
  @keyframes aevko-dropdown-menu-enter {
    from {
      opacity: 0;
      translate: 0 3px;
    }
    to {
      opacity: 1;
      translate: 0 0;
    }
  }
}

import {
  afterEveryRender,
  DestroyRef,
  Directive,
  ElementRef,
  inject,
  input,
  booleanAttribute,
} from '@angular/core';

/** Keeps non-modal surfaces inside the viewport without changing focus ownership. */
@Directive({ selector: '[aevkoFloating]', standalone: true })
export class AevkoFloating {
  readonly aevkoFloating = input(true, { transform: booleanAttribute });
  private readonly element = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  private readonly destroy = inject(DestroyRef);
  constructor() {
    afterEveryRender(() => this.position());
    const view = this.element.ownerDocument.defaultView;
    if (view) {
      const update = () => this.position();
      view.addEventListener('resize', update);
      view.addEventListener('scroll', update, true);
      this.destroy.onDestroy(() => {
        view.removeEventListener('resize', update);
        view.removeEventListener('scroll', update, true);
      });
    }
  }
  private position(): void {
    const panel = this.element;
    const view = panel.ownerDocument.defaultView;
    if (!view || panel.hidden || !this.aevkoFloating()) return;
    const anchor = panel.parentElement?.querySelector<HTMLElement>(
      '[data-slot$="trigger"], input, button',
    );
    if (!anchor) return;
    const rect = anchor.getBoundingClientRect();
    const margin = 8;
    const gap = 6;
    const width = view.innerWidth;
    const height = view.innerHeight;
    if (panel.getAttribute('role') === 'listbox') panel.style.width = `${rect.width}px`;
    panel.style.position = 'fixed';
    panel.style.inset = 'auto';
    panel.style.transform = 'none';
    panel.style.boxSizing = 'border-box';
    panel.style.maxWidth = `${width - margin * 2}px`;
    panel.style.maxHeight = `${height - margin * 2}px`;
    panel.style.overflow = 'auto';
    const size = panel.getBoundingClientRect();
    const side = panel.dataset['side'] ?? 'bottom';
    const align = panel.dataset['align'] ?? 'start';
    let x =
      align === 'end'
        ? rect.right - size.width
        : align === 'center'
          ? rect.left + (rect.width - size.width) / 2
          : rect.left;
    let y = rect.bottom + gap;
    if (side === 'top') y = rect.top - size.height - gap;
    if (side === 'left' || side === 'right') {
      x = side === 'left' ? rect.left - size.width - gap : rect.right + gap;
      y = rect.top;
    } else if (y + size.height > height - margin && rect.top > height - rect.bottom) {
      y = rect.top - size.height - gap;
    } else if (y < margin) y = rect.bottom + gap;
    panel.style.left = `${Math.max(margin, Math.min(x, width - size.width - margin))}px`;
    panel.style.top = `${Math.max(margin, Math.min(y, height - size.height - margin))}px`;
  }
}
